        "L1",
        "L2"
      ]
    }
  },
  {
    "tool": "check_return",
    "arguments": {
      "line_id": "L1",
      "reason": "damaged"
    },
    "result": {
      "eligible": true
    }
  },
  {
    "tool": "check_return",
    "arguments": {
      "line_id": "L2",
      "reason": "changed_mind"
    },
    "result": {
      "eligible": false
    }
  },
  {
    "tool": "create_return",
    "arguments": {
      "order_id": "O17",
      "line_ids": [
        "L1"
      ]
    },
    "result": {
      "ok": true
    }
  }
]

