def reconcile(events):
    latest = {}
    for event in events:
        if event["id"] not in latest or event["seq"] > latest[event["id"]]["seq"]:
            latest[event["id"]] = event
    settled = [event for event in latest.values() if event["status"] == "settled"]
    return {"net_centavos": sum(event["amount_centavos"] for event in settled),
            "ids": sorted(event["id"] for event in settled)}

import re

def expand_ranges(text):
    if not text.strip():
        return []
    result, seen = [], set()
    for raw_token in text.split(","):
        token = raw_token.strip()
        match = re.fullmatch(r"(-?[0-9]+)(?:\.\.(-?[0-9]+))?", token)
        if not match:
            raise ValueError("invalid token")
        start = int(match.group(1))
        end = start if match.group(2) is None else int(match.group(2))
        step = 1 if end >= start else -1
        for value in range(start, end + step, step):
            if value not in seen:
                result.append(value)
                seen.add(value)
    return result
